CREATE TABLE public.gallery_cache (id text PRIMARY KEY, payload jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.gallery_cache TO service_role; ALTER TABLE public.gallery_cache ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.validate_club_fields() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='socios' THEN IF length(trim(NEW.nombre))<1 OR length(NEW.nombre)>200 OR NEW.telefono !~ '^[0-9]{9,15}$' THEN RAISE EXCEPTION 'Nombre o teléfono no válido'; END IF; IF NEW.estado='desactivada' AND (NEW.fecha_baja IS NULL OR coalesce(length(trim(NEW.motivo_baja)),0)=0) THEN RAISE EXCEPTION 'Indica fecha y motivo de baja'; END IF; ELSIF TG_TABLE_NAME='patrocinadores' THEN IF NOT NEW.activo AND (NEW.fecha_baja IS NULL OR NEW.motivo_baja IS NULL) THEN RAISE EXCEPTION 'Indica fecha y motivo de baja'; END IF; ELSIF TG_TABLE_NAME='avisos' THEN IF length(trim(NEW.titulo))<1 OR length(NEW.titulo)>200 OR length(trim(NEW.texto))<1 OR length(NEW.texto)>5000 THEN RAISE EXCEPTION 'Aviso no válido'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER socios_validacion BEFORE INSERT OR UPDATE ON public.socios FOR EACH ROW EXECUTE FUNCTION public.validate_club_fields(); CREATE TRIGGER patrocinadores_validacion BEFORE INSERT OR UPDATE ON public.patrocinadores FOR EACH ROW EXECUTE FUNCTION public.validate_club_fields(); CREATE TRIGGER avisos_validacion BEFORE INSERT OR UPDATE ON public.avisos FOR EACH ROW EXECUTE FUNCTION public.validate_club_fields(); REVOKE ALL ON FUNCTION public.validate_club_fields() FROM PUBLIC;
CREATE POLICY visitas_directiva_borrar ON public.visitas FOR DELETE TO authenticated USING(public.has_club_role('directiva')); GRANT DELETE ON public.visitas TO authenticated; GRANT UPDATE ON public.visitas TO authenticated;
